import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and the current year `now`.

    Only years are compared, so the result is `now - born`. `now` is a
    parameter and the clock is never read. Raises ValueError if `now` is
    earlier than `born`.
    """
    if now < born:
        raise ValueError("now is earlier than born")
    return now - born


def test_age_basic() -> None:
    assert age_at(1990, 2024) == 34
    assert age_at(2000, 2026) == 26


def test_age_born_this_year_is_zero() -> None:
    assert age_at(2026, 2026) == 0


def test_age_one_year() -> None:
    assert age_at(2025, 2026) == 1


def test_age_long_span() -> None:
    assert age_at(1900, 2026) == 126


def test_age_born_in_future_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2027, 2026)


def test_age_future_by_one_year_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)


def test_age_returns_int() -> None:
    assert isinstance(age_at(1980, 2020), int)

